#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-/home/hao/Documents/AI/Course}"
LAB4="$ROOT/Lab/Lab4"
RAG="$LAB4/rag_pipeline"
REL="$RAG/relevance.py"
TEST="$RAG/tests/test_relevance.py"
ENV_FILE="$LAB4/.env"

for item in "$REL" "$ENV_FILE" "$LAB4/docker-compose.yml"; do
  if [[ ! -f "$item" ]]; then
    echo "ERROR: Không tìm thấy $item" >&2
    exit 1
  fi
done

STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="$LAB4/backups/adaptive_filter_$STAMP"
mkdir -p "$BACKUP"
cp "$REL" "$ENV_FILE" "$LAB4/docker-compose.yml" "$BACKUP/"
[[ -f "$TEST" ]] && cp "$TEST" "$BACKUP/"

echo "[1/5] Thay strict filter bằng adaptive filter..."

printf '%s' '' | base64 -d > "$REL"
mkdir -p "$RAG/tests"
touch "$RAG/tests/__init__.py"
printf '%s' '' | base64 -d > "$TEST"

echo "[2/5] Chỉnh ngưỡng..."

python3 - "$ENV_FILE" <<'PY'
from pathlib import Path
import sys

path = Path(sys.argv[1])
updates = {
    "TOP_K": "8",
    "LOW_CONFIDENCE_THRESHOLD": "0.56",
    "HIGH_CONFIDENCE_THRESHOLD": "0.72",
    "MIN_KEYWORD_OVERLAP": "2",
    "MIN_KEYWORD_COVERAGE": "0.50",
    "MAX_CONTEXT_CHUNKS": "3",
}

lines = path.read_text(encoding="utf-8").splitlines()
output = []
seen = set()

for line in lines:
    if "=" in line and not line.lstrip().startswith("#"):
        key = line.split("=", 1)[0].strip()
        if key in updates:
            output.append(f"{key}={updates[key]}")
            seen.add(key)
            continue
    output.append(line)

for key, value in updates.items():
    if key not in seen:
        output.append(f"{key}={value}")

path.write_text("\n".join(output).rstrip() + "\n", encoding="utf-8")
PY

echo "[3/5] Kiểm tra cú pháp..."
find "$RAG" -type d -name '__pycache__' -prune -exec rm -rf {} +
python3 -m py_compile "$REL" "$TEST"

echo "[4/5] Rebuild rag-app..."
cd "$LAB4"
docker compose up -d --build rag-app

RAG_PORT="$(awk -F= '$1 == "RAG_PORT" {print $2}' .env | tail -n 1)"
RAG_PORT="${RAG_PORT:-8001}"
BASE_URL="http://localhost:$RAG_PORT"

for _ in $(seq 1 90); do
  if curl -fsS "$BASE_URL/health" >/dev/null 2>&1; then
    break
  fi
  sleep 2
done
curl -fsS "$BASE_URL/health" >/dev/null

echo "[5/5] Chạy unit test..."
docker compose exec -T rag-app python -m unittest -v tests.test_relevance

echo
echo "DONE: Adaptive filter đã được bật."
echo "UI: $BASE_URL"
echo "Backup: $BACKUP"
echo
echo "Debug một câu bị lọc:"
echo "curl -sS -X POST '$BASE_URL/debug/retrieval' \"
echo "  -H 'Content-Type: application/json' \"
echo "  -d '{\"question\":\"CÂU HỎI CỦA BẠN\"}' | jq"
